/**
 * LLM Service Types
 * Shared type definitions and constants for LLM service modules
 */

// ============================================================================
// Chat Types
// ============================================================================

/**
 * OpenRouter content item (OpenAI-compatible format)
 * Supports text and image content in multi-modal messages
 */
export type OpenRouterContentItem =
  | { type: 'text'; text: string }
  | { type: 'image_url'; image_url: { url: string } };

/**
 * Chat message format for OpenRouter/OpenAI APIs
 * Role: "system" | "user" | "assistant" | "model"
 * Content: Plain text string OR array of content items (for multi-modal)
 */
export type ChatMessage = {
  role: string;
  content: string | OpenRouterContentItem[];
};

// ============================================================================
// Image Generation Types
// ============================================================================

/**
 * Canvas dimensions for image generation
 * - Non-null: Generate and resize to exact dimensions
 * - Null: Use default aspect ratio (16:9)
 */
export type CanvasDimensions = {
  width: number;
  height: number;
} | null;

// ============================================================================
// Prompt Enhancement Types
// ============================================================================

/**
 * Optional context for prompt enhancement
 * Allows AI to tailor enhancements based on user preferences
 */
export interface PromptEnhanceContext {
  industry?: string;      // e.g., "tech", "finance", "healthcare"
  style?: string;         // e.g., "professional", "creative", "minimal"
  brandColors?: string[]; // e.g., ["#1a73e8", "#34a853"]
}

// ============================================================================
// Constants
// ============================================================================

/**
 * LinkedIn profile zone constraint
 * Profile photo occupies bottom-left corner (0,0 to 568,264)
 * Ensures AI doesn't place important content in this zone
 */
export const PROFILE_ZONE_CONSTRAINT =
  " IMPORTANT CONSTRAINT: Do NOT place any text, logos, or important visual elements in the bottom-left corner area (coordinates 0,0 to 568,264).";
